mapper.select:
SELECT * FROM ( SELECT DISTINCT pl.id, pl.title, pl.writer_uid, pl.type, pl.status, pl.price, pl.location, pl.thumbnail, pl.view_count, pl.created_at, pl.updated_at, pl.bumped_at, ui.nickname AS writer_name, (SELECT COUNT(*) FROM chatroom WHERE pot_listing_id = pl.id) AS chatroom_count, (SELECT COUNT(*) FROM pot_listing_bookmark WHERE pot_listing_id = pl.id) AS bookmark_count FROM pot_listing pl JOIN user_info ui on ui.uuid = pl.writer_uid LEFT JOIN pot_listing_tag_mapping ptm ON ptm.pot_listing_id = pl.id LEFT JOIN plant_tag pt ON pt.tag_id = ptm.plant_tag_id WHERE 1=1
AND pl.bumped_at < #{cursorId}
AND (pl.title LIKE '%' || #{keyword} || '%' OR pl.description LIKE '%' || #{keyword} || '%' OR ui.nickname LIKE '%' || #{keyword} || '%')
AND (ui.nickname LIKE '%' || #{keyword} || '%')
AND (pl.description LIKE '%' || #{keyword} || '%')
AND (pl.title LIKE '%' || #{keyword} || '%')
AND (pl.location LIKE '%' || #{location} || '%')
AND pt.tag_id IN
#{tagId}
ORDER BY pl.bumped_at DESC ) WHERE ROWNUM <= #{size}

SELECT *
FROM (
SELECT pl.*,
(SELECT COUNT(*) FROM chatroom WHERE pot_listing_id = pl.id) AS chatroom_count,
(SELECT COUNT(*) FROM pot_listing_bookmark WHERE pot_listing_id = pl.id) AS bookmark_count,
ROW_NUMBER() OVER (ORDER BY pl.created_at DESC) AS rn
FROM pot_listing pl
WHERE pl.writer_uid = #{id}
)
WHERE rn <= #{limit}
